#include <stdio.h>
#include <pthread.h>
int shared_var = 0;
void *thread_func(void *arg) {
    shared_var++;  // Intended to be atomic but may be interrupted
    return NULL;
}
int main() {
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, thread_func, NULL);
    pthread_create(&thread2, NULL, thread_func, NULL);
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);
    printf("Shared var: %d\n", shared_var);  // May output 1 or 2, demonstrating potential violation
    return 0;
}
